// Builds src/content/packs.generated.ts from the JSON packs in
// src/content/packs/. The JSON files are the source of truth; edit them,
// then run:
//   npm run build:content          write the generated file
//   npm run build:content -- --check   fail if it is out of date (CI)
// Content rules (ids, targets, review status) are checked by
// scripts/validate-content.ts; this script checks the pack shape.

import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

const PACK_DIR = 'src/content/packs';
const OUT = 'src/content/packs.generated.ts';

const DHIKR_KEYS = ['id', 'label', 'arabic', 'transliteration', 'meaning', 'source', 'reviewStatus'] as const;
const COLLECTION_KEYS = ['id', 'title', 'subtitle', 'items'] as const;
const ITEM_KEYS = ['itemId', 'dhikrId', 'target', 'phase'] as const;

type Json = Record<string, unknown>;

function exactKeys(o: unknown, keys: readonly string[], where: string): Json {
  if (typeof o !== 'object' || o === null || Array.isArray(o)) throw new Error(`${where}: not an object`);
  const actual = Object.keys(o).sort();
  const expected = [...keys].sort();
  if (actual.join() !== expected.join()) {
    throw new Error(`${where}: keys must be exactly ${expected.join(', ')} (got ${actual.join(', ')})`);
  }
  return o as Json;
}

export function readPacks(dir = PACK_DIR): { file: string; pack: Json }[] {
  return readdirSync(dir)
    .filter((f) => f.endsWith('.json'))
    .sort()
    .map((file) => {
      const pack = JSON.parse(readFileSync(join(dir, file), 'utf8')) as Json;
      exactKeys(pack, ['format', 'id', 'version', 'title', 'adhkar', 'collections'], file);
      if (pack.format !== 'dhikrgeed-pack') throw new Error(`${file}: format must be "dhikrgeed-pack"`);
      if (`${pack.id}.json` !== file) throw new Error(`${file}: id must match the file name`);
      if (!Number.isInteger(pack.version) || (pack.version as number) < 1) throw new Error(`${file}: bad version`);
      if (!Array.isArray(pack.adhkar) || !Array.isArray(pack.collections)) throw new Error(`${file}: bad lists`);
      pack.adhkar.forEach((d, i) => exactKeys(d, DHIKR_KEYS, `${file} adhkar[${i}]`));
      pack.collections.forEach((c, i) => {
        const col = exactKeys(c, COLLECTION_KEYS, `${file} collections[${i}]`);
        if (!Array.isArray(col.items)) throw new Error(`${file} collections[${i}]: items must be a list`);
        col.items.forEach((it, j) => exactKeys(it, ITEM_KEYS, `${file} collections[${i}].items[${j}]`));
      });
      return { file, pack };
    });
}

export function generate(packs: { file: string; pack: Json }[]): string {
  const adhkar = packs.flatMap((p) => p.pack.adhkar as unknown[]);
  const collections = packs.flatMap((p) => p.pack.collections as unknown[]);
  const meta = packs.map((p) => ({ id: p.pack.id, version: p.pack.version, title: p.pack.title }));
  // Any pack version bump changes the content version, so new rounds get new snapshots.
  const contentVersion = packs.reduce((sum, p) => sum + (p.pack.version as number), 0);
  return [
    '// GENERATED by scripts/build-content.ts from src/content/packs/*.json. Do not edit.',
    '',
    "import type { Collection, Dhikr } from './types.ts';",
    '',
    `export const CONTENT_VERSION = ${contentVersion};`,
    '',
    `export const PACKS = ${JSON.stringify(meta, null, 2)} as const;`,
    '',
    `export const ADHKAR: readonly Dhikr[] = ${JSON.stringify(adhkar, null, 2)};`,
    '',
    `export const COLLECTIONS: readonly Collection[] = ${JSON.stringify(collections, null, 2)};`,
    '',
  ].join('\n');
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const out = generate(readPacks());
  if (process.argv.includes('--check')) {
    if (readFileSync(OUT, 'utf8') !== out) {
      console.error(`${OUT} is out of date. Run: npm run build:content`);
      process.exit(1);
    }
    console.log(`${OUT} is up to date.`);
  } else {
    writeFileSync(OUT, out);
    console.log(`Wrote ${OUT}.`);
  }
}
